      out.write("\r\n");
      out.write("    <script>\r\n");
      out.write("        (function () {\r\n");
      out.write("            /* 1. Dismissible alerts */\r\n");
      out.write("            document.querySelectorAll(\"[data-dismiss-alert]\").forEach(function (btn) {\r\n");
      out.write("                btn.addEventListener(\"click\", function () {\r\n");
      out.write("                    var box = btn.closest(\".pf-alert\");\r\n");
      out.write("                    if (box) box.remove();\r\n");
      out.write("                });\r\n");
      out.write("            });\r\n");
      out.write("\r\n");
      out.write("            /* 2. Dirty-state tracker + Reset for personal info form */\r\n");
      out.write("            var infoForm = document.getElementById(\"profileInfoForm\");\r\n");
      out.write("            var syncChip = document.getElementById(\"profileSyncChip\");\r\n");
      out.write("            var resetBtn = document.getElementById(\"profileResetBtn\");\r\n");
      out.write("\r\n");
      out.write("            if (infoForm) {\r\n");
      out.write("                var trackedFields = infoForm.querySelectorAll(\"input[data-initial]\");\r\n");
      out.write("\r\n");
      out.write("                function checkDirty() {\r\n");
      out.write("                    var dirty = false;\r\n");
      out.write("                    trackedFields.forEach(function (input) {\r\n");
      out.write("                        if (input.value !== input.getAttribute(\"data-initial\")) {\r\n");
      out.write("                            dirty = true;\r\n");
      out.write("                        }\r\n");
      out.write("                    });\r\n");
      out.write("\r\n");
      out.write("                    if (syncChip) {\r\n");
      out.write("                        if (dirty) {\r\n");
      out.write("                            syncChip.textContent = \"• Có thay đổi chưa lưu\";\r\n");
      out.write("                            syncChip.className = \"pf-chip pf-chip-warn\";\r\n");
      out.write("                        } else {\r\n");
      out.write("                            syncChip.textContent = \"✓ Đã đồng bộ\";\r\n");
      out.write("                            syncChip.className = \"pf-chip pf-chip-accent\";\r\n");
      out.write("                        }\r\n");
      out.write("                    }\r\n");
      out.write("                    if (resetBtn) {\r\n");
      out.write("                        resetBtn.hidden = !dirty;\r\n");
      out.write("                    }\r\n");
      out.write("                }\r\n");
      out.write("\r\n");
      out.write("                trackedFields.forEach(function (input) {\r\n");
      out.write("                    input.addEventListener(\"input\", checkDirty);\r\n");
      out.write("                });\r\n");
      out.write("\r\n");
      out.write("                if (resetBtn) {\r\n");
      out.write("                    resetBtn.addEventListener(\"click\", function () {\r\n");
      out.write("                        trackedFields.forEach(function (input) {\r\n");
      out.write("                            input.value = input.getAttribute(\"data-initial\") || \"\";\r\n");
      out.write("                        });\r\n");
      out.write("                        checkDirty();\r\n");
      out.write("                    });\r\n");
      out.write("                }\r\n");
      out.write("            }\r\n");
      out.write("\r\n");
      out.write("            /* 3. Live password strength meter + 4-rule chips + confirm match */\r\n");
      out.write("            var pw = document.getElementById(\"newPassword\");\r\n");
      out.write("            var cf = document.getElementById(\"confirmPassword\");\r\n");
      out.write("            var segs = document.querySelectorAll(\".profile-pw-seg\");\r\n");
      out.write("            var strengthLbl = document.getElementById(\"pwStrengthLabel\");\r\n");
      out.write("            var matchLbl = document.getElementById(\"pwMatchLabel\");\r\n");
      out.write("            var ruleEls = {\r\n");
      out.write("                len: document.querySelector('.pf-pw-rule[data-rule=\"len\"]'),\r\n");
      out.write("                case: document.querySelector('.pf-pw-rule[data-rule=\"case\"]'),\r\n");
      out.write("                num: document.querySelector('.pf-pw-rule[data-rule=\"num\"]'),\r\n");
      out.write("                sym: document.querySelector('.pf-pw-rule[data-rule=\"sym\"]')\r\n");
      out.write("            };\r\n");
      out.write("\r\n");
      out.write("            function updatePwUi() {\r\n");
      out.write("                if (!pw) return;\r\n");
      out.write("                var v = pw.value || \"\";\r\n");
      out.write("                var checks = {\r\n");
      out.write("                    len: v.length >= 8,\r\n");
      out.write("                    case: /[A-Z]/.test(v) && /[a-z]/.test(v),\r\n");
      out.write("                    num: /[0-9]/.test(v),\r\n");
      out.write("                    sym: /[^A-Za-z0-9]/.test(v)\r\n");
      out.write("                };\r\n");
      out.write("\r\n");
      out.write("                Object.keys(ruleEls).forEach(function (key) {\r\n");
      out.write("                    if (ruleEls[key]) {\r\n");
      out.write("                        ruleEls[key].classList.toggle(\"is-met\", checks[key]);\r\n");
      out.write("                    }\r\n");
      out.write("                });\r\n");
      out.write("\r\n");
      out.write("                var score = 0;\r\n");
      out.write("                if (v.length > 0) {\r\n");
      out.write("                    if (checks.len) score++;\r\n");
      out.write("                    if (checks.case) score++;\r\n");
      out.write("                    if (checks.num) score++;\r\n");
      out.write("                    if (checks.sym) score++;\r\n");
      out.write("                    score = Math.max(1, score);\r\n");
      out.write("                }\r\n");
      out.write("\r\n");
      out.write("                var colors = [\"#e2e8f0\", \"#ef4444\", \"#f59e0b\", \"#10b981\", \"#075c45\"];\r\n");
      out.write("                var labels = [\r\n");
      out.write("                    \"Chưa nhập mật khẩu mới\",\r\n");
      out.write("                    \"Mật khẩu yếu (cần tối thiểu 8 ký tự)\",\r\n");
      out.write("                    \"Mật khẩu trung bình\",\r\n");
      out.write("                    \"Mật khẩu khá mạnh\",\r\n");
      out.write("                    \"Mật khẩu rất mạnh\"\r\n");
      out.write("                ];\r\n");
      out.write("\r\n");
      out.write("                segs.forEach(function (el, idx) {\r\n");
      out.write("                    el.style.background = (idx < score) ? colors[score] : \"#e2e8f0\";\r\n");
      out.write("                });\r\n");
      out.write("                if (strengthLbl) {\r\n");
      out.write("                    strengthLbl.textContent = labels[score];\r\n");
      out.write("                    strengthLbl.style.color = score > 0 ? colors[score] : \"#64748b\";\r\n");
      out.write("                }\r\n");
      out.write("\r\n");
      out.write("                if (cf && matchLbl) {\r\n");
      out.write("                    if (!cf.value) {\r\n");
      out.write("                        matchLbl.textContent = \"\";\r\n");
      out.write("                    } else if (cf.value === v) {\r\n");
      out.write("                        matchLbl.textContent = \"✓ Khớp mật khẩu\";\r\n");
      out.write("                        matchLbl.style.color = \"#047857\";\r\n");
      out.write("                    } else {\r\n");
      out.write("                        matchLbl.textContent = \"Chưa khớp\";\r\n");
      out.write("                        matchLbl.style.color = \"#dc2626\";\r\n");
      out.write("                    }\r\n");
      out.write("                }\r\n");
      out.write("            }\r\n");
      out.write("\r\n");
      out.write("            if (pw) pw.addEventListener(\"input\", updatePwUi);\r\n");
      out.write("            if (cf) cf.addEventListener(\"input\", updatePwUi);\r\n");
      out.write("\r\n");
      out.write("            /* 4. Quick section nav active state */\r\n");
      out.write("            var navLinks = document.querySelectorAll(\"[data-pf-nav]\");\r\n");
      out.write("            navLinks.forEach(function (link) {\r\n");
      out.write("                link.addEventListener(\"click\", function () {\r\n");
      out.write("                    navLinks.forEach(function (other) { other.classList.remove(\"is-active\"); });\r\n");
      out.write("                    link.classList.add(\"is-active\");\r\n");
      out.write("                });\r\n");
      out.write("            });\r\n");
      out.write("        })();\r\n");
      out.write("    </script>\r\n");
      out.write("    <!-- PRECISION IMAGE CROP & CLOUDINARY UPLOAD STUDIO MODAL -->\r\n");
      out.write("    <div id=\"pfMediaModal\" class=\"pf-modal\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"pfMediaTitle\" hidden>\r\n");
      out.write("        <div class=\"pf-modal-backdrop\" data-close-media-modal></div>\r\n");
      out.write("        <div class=\"pf-modal-dialog\">\r\n");
      out.write("            <div class=\"pf-modal-head\">\r\n");
      out.write("                <div>\r\n");
      out.write("                    <h2 class=\"pf-modal-title\" id=\"pfMediaTitle\">Chỉnh sửa ảnh đại diện</h2>\r\n");
